    unsigned long maskGreen = (g_colorMaskGreen << 16) | g_colorMaskGreen;
    unsigned long maskRed = (g_colorMaskRed << 16) | g_colorMaskRed;
    Bitmap16Bit fadeFrom(WINDOW_SCREEN_WIDTH, WINDOW_SCREEN_HEIGHT);
    RECT screenRect;

